package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
)

// User represents the application user model
type User struct {
	ID        int    `json:"id" db:"id"`
	Username  string `json:"username" db:"username"`
	Email     string `json:"email" db:"email"`
	Role      string `json:"role" db:"role"`
	IsAdmin   bool   `json:"is_admin" db:"is_admin"`
	APIKey    string `json:"api_key" db:"api_key"`
	RateLimit int    `json:"rate_limit" db:"rate_limit"`
	OrgID     int    `json:"org_id" db:"org_id"`
}

// In-memory store for demo
var users = map[int]*User{
	1: {ID: 1, Username: "alice", Email: "alice@corp.internal", Role: "viewer", IsAdmin: false, APIKey: "ak_viewer_001", RateLimit: 100, OrgID: 1},
	2: {ID: 2, Username: "bob", Email: "bob@corp.internal", Role: "editor", IsAdmin: false, APIKey: "ak_editor_002", RateLimit: 500, OrgID: 1},
}

// UpdateProfileHandler allows users to update their profile
func UpdateProfileHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPut && r.Method != http.MethodPatch {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Extract user ID from basic auth (simplified)
	userID := authenticateRequest(r)
	if userID == 0 {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	user, exists := users[userID]
	if !exists {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}

	// Decode the incoming JSON directly into the user struct
	// This allows any field in the struct to be overwritten
	decoder := json.NewDecoder(r.Body)
	if err := decoder.Decode(user); err != nil {
		http.Error(w, "Invalid JSON", http.StatusBadRequest)
		return
	}

	// Preserve the original ID to prevent ID reassignment
	user.ID = userID

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(user)
}

// GetProfileHandler returns user profile
func GetProfileHandler(w http.ResponseWriter, r *http.Request) {
	userID := authenticateRequest(r)
	if userID == 0 {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}
	user, exists := users[userID]
	if !exists {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(user)
}

func authenticateRequest(r *http.Request) int {
	// Simplified: check X-User-ID header (in prod this would be JWT/session)
	auth := r.Header.Get("Authorization")
	if strings.HasPrefix(auth, "Bearer user1") {
		return 1
	}
	if strings.HasPrefix(auth, "Bearer user2") {
		return 2
	}
	return 0
}

// HealthHandler for ALB health checks
func HealthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/profile", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			GetProfileHandler(w, r)
		case http.MethodPut, http.MethodPatch:
			UpdateProfileHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})
	mux.HandleFunc("/health", HealthHandler)

	fmt.Println("Starting user-profile-service on :8080")
	http.ListenAndServe(":8080", mux)
}
